def transform(g):
    import copy
    g=[r[:] for r in g]
    H,W=len(g),len(g[0])
    # find divider: full-length constant-color line != background
    from collections import Counter
    # background = most common color
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    div=None; dv=None
    for c in range(W):
        col={g[r][c] for r in range(H)}
        if len(col)==1:
            v=col.pop()
            if v!=bg and sum(1 for r in range(H) if g[r][c]==v)==H:
                div,dv=c,v; break
    # find non-bg, non-divider pixels
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (bg,dv)]
    cols=[c for _,c in cells]
    c0,c1=min(cols),max(cols)
    w=c1-c0+1
    if c1<div:
        m0,m1=div-w,div-1; line=div-w-1
    else:
        m0,m1=div+1,div+w; line=div+w+1
    for r in range(H):
        for c in range(m0,m1+1):
            src = c1-(c-m0) if c1<div else c1-(c-m0)
            # mirror: flipped horizontally
            src = c0 + (c1 - c) if False else None
        # do explicit flip: mirrored col m0+k gets original col c1-k
    for k in range(w):
        for r in range(H):
            g[r][m0+k]=g[r][c1-k]
    for r in range(H):
        g[r][line]=8
    return g

