def transform(g):
    g=[r[:] for r in g]
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    div=dv=None
    for c in range(W):
        if all(g[r][c]==g[0][c] for r in range(H)) and g[0][c]!=bg:
            div,dv=c,g[0][c]; break
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (bg,dv)]
    cols=[c for _,c in cells]
    c0,c1=min(cols),max(cols)
    w=c1-c0+1
    if c1<div:
        m0,line=div-w,div-w-1
    else:
        m0,line=div+1,div+w+1
    shape=[[g[r][c] for c in range(c0,c1+1)] for r in range(H)]
    # clear original bbox
    for r in range(H):
        for c in range(c0,c1+1):
            g[r][c]=bg
    # place mirrored shape in mirror region
    for k in range(w):
        for r in range(H):
            g[r][m0+k]=shape[r][w-1-k]
    for r in range(H):
        g[r][line]=8
    return g

